class JarvisApp extends StatefulWidget { const JarvisApp({super.key}); @override State<JarvisApp> createState()=>_JarvisAppState(); }
class _JarvisAppState extends State<JarvisApp> {
  ThemeMode mode=ThemeMode.dark;
  final prefs=Prefs();
  @override Widget build(BuildContext c)=>MaterialApp(title:'JARVIS NEO Mobile',debugShowCheckedModeBanner:false,themeMode:mode,
    darkTheme:ThemeData.dark(useMaterial3:true).copyWith(colorScheme:ColorScheme.fromSeed(seedColor:Colors.cyan,brightness:Brightness.dark),scaffoldBackgroundColor:const Color(0xff070b12)),
    theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:Colors.cyan),scaffoldBackgroundColor:const Color(0xfff4f7fb)),
    home:Home(onTheme:(v)=>setState(()=>mode=v?ThemeMode.light:ThemeMode.dark)));
}

class Home extends StatefulWidget { final ValueChanged<bool> onTheme; const Home({super.key,required this.onTheme}); @override State<Home> createState()=>_HomeState(); }
class _HomeState extends State<Home> {
  int tab=0; final tts=FlutterTts(); final chat=ChatService(); final log=ActivityLog();
  final pages=['Command','Devices','Files','Routines','Sentinel','Settings'];
  @override Widget build(BuildContext c){ final body=[CommandPage(chat:chat,tts:tts,log:log),const DevicesPage(),const FilesPage(),const RoutinesPage(),const SentinelPage(),SettingsPage(onTheme:widget.onTheme)];
    return Scaffold(appBar:AppBar(title:Row(children:[Container(width:10,height:10,decoration:BoxDecoration(shape:BoxShape.circle,color:Colors.cyan,boxShadow:[BoxShadow(color:Colors.cyan.withOpacity(.8),blurRadius:12)])),const SizedBox(width:10),Text('J.A.R.V.I.S. NEO',style:const TextStyle(fontWeight:FontWeight.w700,letterSpacing:1.2))]),actions:[IconButton(onPressed:()=>setState(()=>tab=5),icon:const Icon(Icons.settings_outlined))]),
      body:body[tab],bottomNavigationBar:NavigationBar(selectedIndex:tab,onDestinationSelected:(i)=>setState(()=>tab=i),destinations:const [NavigationDestination(icon:Icon(Icons.mic_none),selectedIcon:Icon(Icons.mic),label:'JARVIS'),NavigationDestination(icon:Icon(Icons.devices_other),label:'Devices'),NavigationDestination(icon:Icon(Icons.folder_open),label:'Files'),NavigationDestination(icon:Icon(Icons.auto_awesome),label:'Routines'),NavigationDestination(icon:Icon(Icons.shield_outlined),label:'Sentinel'),NavigationDestination(icon:Icon(Icons.tune),label:'Settings') ])); }
}

class CommandPage extends StatefulWidget { final ChatService chat; final FlutterTts tts; final ActivityLog log; const CommandPage({super.key,required this.chat,required this.tts,required this.log}); @override State<CommandPage> createState()=>_CommandPageState(); }
class _CommandPageState extends State<CommandPage>{ final input=TextEditingController(); final messages=<Map<String,String>>[]; bool busy=false;
  Future<void> send() async { final q=input.text.trim(); if(q.isEmpty||busy)return; input.clear(); setState(()=>messages.add({'role':'user','text':q})); busy=true; setState((){}); final a=await widget.chat.ask(q); widget.log.add('AI','Conversation'); setState(()=>messages.add({'role':'jarvis','text':a})); busy=false; if(await Prefs().getBool('voice',true)) widget.tts.speak(a); setState((){}); }
  @override Widget build(BuildContext c)=>Column(children:[Expanded(child:messages.isEmpty?Center(child:Column(mainAxisSize:MainAxisSize.min,children:[Icon(Icons.auto_awesome,size:72,color:Colors.cyan.withOpacity(.75)),const SizedBox(height:18),const Text('Bonjour. JARVIS NEO Mobile est opérationnel.',style:TextStyle(fontSize:18)),const SizedBox(height:8),Text('Commande vocale, appareils, fichiers et automatisations.',style:TextStyle(color:Colors.grey))])):ListView.builder(padding:const EdgeInsets.all(16),itemCount:messages.length,itemBuilder:(c,i){final m=messages[i];final user=m['role']=='user';return Align(alignment:user?Alignment.centerRight:Alignment.centerLeft,child:Container(margin:const EdgeInsets.only(bottom:10),padding:const EdgeInsets.all(14),constraints:BoxConstraints(maxWidth:MediaQuery.of(c).size.width*.82),decoration:BoxDecoration(borderRadius:BorderRadius.circular(18),color:user?Colors.cyan.withOpacity(.18):Colors.white.withOpacity(.06),border:Border.all(color:user?Colors.cyan.withOpacity(.25):Colors.white.withOpacity(.08))),child:Text(m['text']!)));})),
    SafeArea(child:Padding(padding:const EdgeInsets.fromLTRB(12,8,12,12),child:Row(children:[Expanded(child:TextField(controller:input,onSubmitted:(_)=>send(),decoration:InputDecoration(hintText:'Parler à JARVIS…',prefixIcon:const Icon(Icons.chat_bubble_outline),filled:true,border:OutlineInputBorder(borderRadius:BorderRadius.circular(18),borderSide:BorderSide.none)))),const SizedBox(width:8),FloatingActionButton(onPressed:busy?null:send,child:busy?const SizedBox(width:22,height:22,child:CircularProgressIndicator(strokeWidth:2)):const Icon(Icons.arrow_upward))])))]);
}

class ChatService { Future<String> ask(String text) async { final p=await SharedPreferences.getInstance(); final key=p.getString('groq_key')??''; final model=p.getString('groq_model')??'llama-3.1-8b-instant'; if(key.isEmpty)return 'Mode local/préparation : configure une clé Groq ou connecte JARVIS NEO PC pour une réponse IA complète. Commande reçue : "$text"'; try { final r=await http.post(Uri.parse('https://api.groq.com/openai/v1/chat/completions'),headers:{'Authorization':'Bearer $key','Content-Type':'application/json'},body:jsonEncode({'model':model,'messages':[{'role':'system','content':'You are JARVIS NEO Mobile. Be concise, helpful and action-oriented.'},{'role':'user','content':text}],'temperature':.4}),); if(r.statusCode==200){final j=jsonDecode(r.body);return j['choices'][0]['message']['content']??'Réponse vide.';} return 'Le fournisseur IA a répondu ${r.statusCode}. Bascule locale recommandée.';}catch(e){return 'Connexion IA indisponible. JARVIS reste en mode local.';} } }

class Prefs { Future<bool> getBool(String k,bool d)async=>(await SharedPreferences.getInstance()).getBool(k)??d; }
class ActivityLog { final entries=<String>[]; void add(String type,String text){entries.insert(0,'$type • $text');if(entries.length>100)entries.removeLast();} }

