class SentinelPage extends StatelessWidget { const SentinelPage({super.key}); @override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[Container(padding:const EdgeInsets.all(20),decoration:BoxDecoration(borderRadius:BorderRadius.circular(22),border:Border.all(color:Colors.cyan.withOpacity(.3)),gradient:LinearGradient(colors:[Colors.cyan.withOpacity(.12),Colors.transparent])),child:const Row(children:[Icon(Icons.shield,color:Colors.cyan,size:42),SizedBox(width:14),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('SENTINEL',style:TextStyle(fontSize:20,fontWeight:FontWeight.bold)),Text('Surveillance intelligente activée')]))])),const SizedBox(height:14),const ActionTile('Confidentialité','Permissions, caméra, micro, localisation et accès applicatifs',Icons.lock_outline,(){ }),const ActionTile('Réseau','Qualité, connexions et anomalies',Icons.wifi_find,(){ }),const ActionTile('Applications','Comportements et accès inhabituels',Icons.apps,(){ }),const ActionTile('Stockage','Analyse des fichiers et risques potentiels',Icons.sd_storage,(){ })]); }

class SettingsPage extends StatefulWidget { final ValueChanged<bool> onTheme; const SettingsPage({super.key,required this.onTheme}); @override State<SettingsPage> createState()=>_SettingsPageState(); }
class _SettingsPageState extends State<SettingsPage>{ final keyCtrl=TextEditingController(); bool voice=true, auto=false; String model='llama-3.1-8b-instant'; @override void initState(){super.initState();load();} Future<void>load()async{final p=await SharedPreferences.getInstance();keyCtrl.text=p.getString('groq_key')??'';voice=p.getBool('voice')??true;auto=p.getBool('auto')??false;model=p.getString('groq_model')??model;setState((){});} Future<void>save()async{final p=await SharedPreferences.getInstance();await p.setString('groq_key',keyCtrl.text.trim());await p.setBool('voice',voice);await p.setBool('auto',auto);await p.setString('groq_model',model);if(mounted)ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('Paramètres enregistrés')));}
 @override Widget build(BuildContext c)=>ListView(padding:const EdgeInsets.all(16),children:[const SectionTitle('IA & tokens'),TextField(controller:keyCtrl,obscureText:true,decoration:const InputDecoration(labelText:'Clé API Groq',helperText:'Stockée localement. Jamais codée en dur.')),const SizedBox(height:12),DropdownButtonFormField(value:model,decoration:const InputDecoration(labelText:'Modèle cloud'),items:const ['llama-3.1-8b-instant','llama-3.3-70b-versatile','qwen/qwen3-32b'].map((x)=>DropdownMenuItem(value:x,child:Text(x))).toList(),onChanged:(v)=>setState(()=>model=v!)),SwitchListTile(title:const Text('Voix'),subtitle:const Text('Réponse vocale de JARVIS'),value:voice,onChanged:(v)=>setState(()=>voice=v)),SwitchListTile(title:const Text('Autonomie adaptative'),subtitle:const Text('Choisir automatiquement cloud/local selon le contexte'),value:auto,onChanged:(v)=>setState(()=>auto=v)),const Divider(),const SectionTitle('Sécurité'),const ListTile(leading:Icon(Icons.fingerprint),title:Text('Biométrie + PIN'),subtitle:Text('Déverrouillage et actions sensibles')),const ListTile(leading:Icon(Icons.admin_panel_settings),title:Text('Permissions par application'),subtitle:Text('Accès précis et révocable')),const Divider(),const SectionTitle('Compte & synchronisation'),const ListTile(leading:Icon(Icons.passkey),title:Text('Compte JARVIS NEO'),subtitle:Text('Passkey / biométrie / profils')),const ListTile(leading:Icon(Icons.backup),title:Text('Sauvegarde chiffrée'),subtitle:Text('Sélective, automatique et restaurable')),FilledButton.icon(onPressed:save,icon:const Icon(Icons.save),label:const Text('Enregistrer'))]); }

